"""RoboPaint episode. Motions use the public robot client, camera calibration and observed RGB only."""
import os,sys,json,time
sys.path.insert(0,'/opt/tools')
import numpy as np
from PIL import Image
from rcb_client import Robot
ROOT='/app/output'
r=Robot()
Q=np.array([0.,1.,0.,0.])
Z=.0202
S=.227185/1024

def observe(tag,cameras=['canvas_cam','practice_cam','scene_cam','side_cam'],depth=False):
 o=r.get_obs(cameras=cameras,depth=depth)
 o.save(f'{ROOT}/{tag}')
 for c,a in o.last.items():Image.fromarray(a).save(f'{ROOT}/{tag}_{c}.png')
 return o

def execute(rows,tag='move',cameras=['practice_cam'],fps=5):
 rows=np.asarray(rows)
 for k in range(0,len(rows),180):
  out=r.submit('ee_pose',rows[k:k+180],dt=.05,cameras=cameras,video='frames',video_fps=fps,note=tag)
  out.save(f'{ROOT}/log/{int(out.meta["calls"]):04d}_{tag}')
  print(tag,out.meta.get('calls'),out.meta.get('control_steps'),out.meta.get('plan'),flush=True)
  if out.stopped or out.done:raise RuntimeError(out.meta)
 return out

def move(p,speed=.06,settle=.35,tag='move'):
 o=r.get_obs(cameras=[]); start=o.group('tcp_pose',now=True)[:3]
 n=max(1,int(np.ceil(np.linalg.norm(np.array(p)-start)/speed/.05)))
 rows=[[*v,*Q] for v in np.linspace(start,p,n+1)[1:]]
 rows += [[*p,*Q]]*int(settle/.05)
 return execute(rows,tag)

def park():
 o=r.get_obs(cameras=[]); p=o.group('tcp_pose',now=True)[:3]; move([p[0],p[1],.09]);move([-.25,.0,.10])

def xy(u,v,practice=False):
 return np.array([-.1+(512-v)*S, (0 if not practice else -.1856)+(512-u)*S])

if __name__=='__main__':
 if sys.argv[1]=='park':park();observe('park',depth=True)
PY
